import {contact} from './ladder.mjs';
export const timerStages=['AP','BP','BM','AM'];
const labels=['A+ · sensor a1','B+ · sensor b1','B− · sensor b0','A− · sensor a0'];
export function createTimers(panel,onCommand,onTimer){const area=document.createElement('section');area.className='timer-panel';area.innerHTML=`<span class="eyebrow">TON · ESPERAS AL LLEGAR</span><p>PT = espera ajustada; ET = tiempo transcurrido; Q = espera cumplida. El pistón mantiene su posición. Ajusta PT con RUN=0.</p><div class="timer-settings">${timerStages.map((st,i)=>`<label>T${i+1} · ${labels[i]}<span><input type="number" min="0" max="5" step="0.2" value="1" data-timer="${st}" aria-label="T${i+1}, espera en ${labels[i]}, segundos"> s</span></label>`).join('')}</div><div id="tonNetworks"></div><p>TON no retentivo: IN=0 borra ET y Q. Las redes solo temporizan en automático. PT=0 permite continuar al detectar el extremo.</p></section>`;panel.querySelector('#ladderRungs').before(area);area.addEventListener('change',e=>{if(e.target.matches('[data-timer]'))onTimer(e.target.dataset.timer,e.target.value)});
 const counter=document.createElement('section');counter.className='counter-panel';counter.innerHTML=`<span class="eyebrow">C1 · CTU · LOTE DE 5 CICLOS</span><div class="counter-read"><strong id="countValue">0 / 5</strong><span id="countState"></span><button id="resetCount">Reiniciar C1</button></div><progress id="cycleProgress" max="5" value="0" aria-label="Ciclos completos del lote"></progress><div id="ctuNetwork"></div><p>CU: pulso de fin de A− con T4.Q. CV = ciclos contados; PV = objetivo (5). CV aumenta una vez por ciclo. C1.Q bloquea Marcha automática al llegar a 5. Reiniciar C1 requiere RUN=0, a0 y b0; no arranca el lote.</p>`;panel.querySelector('.operator-panel').after(counter);counter.querySelector('#resetCount').onclick=()=>onCommand('resetCount');
 let cache='';return (s,disabled)=>{for(const st of timerStages){const input=area.querySelector(`[data-timer="${st}"]`);input.disabled=s.run||disabled;if(document.activeElement!==input)input.value=s.delays[st];}counter.querySelector('#resetCount').disabled=disabled||s.run||!s.i0||!s.i2||s.fault;counter.querySelector('#countValue').textContent=s.cycles+' / '+s.target;counter.querySelector('#countState').textContent=s.complete?'LOTE TERMINADO · C1.Q=1':'C1.Q=0';counter.querySelector('#cycleProgress').value=s.cycles;
 const ts=s.scan?.timers||s.timers,key=JSON.stringify([ts,s.delays,s.cycles,s.complete,s.countPulse]);if(key===cache)return;cache=key;
 area.querySelector('#tonNetworks').innerHTML=timerStages.map((st,i)=>{const t=ts[st]||{input:false,et:0,pt:s.delays[st],q:false};return `<div class="ton-network ${t.input?'timing':''}"><svg viewBox="0 0 420 88" role="img" aria-label="T${i+1}, IN ${Number(t.input)}, ET ${t.et.toFixed(2)} segundos, PT ${t.pt} segundos, Q ${Number(t.q)}"><path class="rail on" d="M15 10V68"/><path class="wire on" d="M15 35H70"/>${contact({tag:['A+ ∧ a1','B+ ∧ b1','B− ∧ b0','A− ∧ a0'][i],pass:t.input},76,35)}<path class="wire ${t.input?'on':''}" d="M82 35H165"/><g class="${t.input?'on':''}"><rect x="165" y="8" width="180" height="61" rx="4"/><text x="255" y="24">TON T${i+1}</text><text x="255" y="42">ET ${t.et.toFixed(2)} / PT ${t.pt.toFixed(1)} s</text><text x="255" y="58">Q = ${Number(t.q)}</text></g><path class="wire ${t.q?'on':''}" d="M345 35H405"/></svg><progress max="${t.pt||1}" value="${t.pt?t.et:Number(t.q)}" aria-label="Progreso T${i+1}"></progress></div>`}).join('');
 counter.querySelector('#ctuNetwork').innerHTML=`<svg viewBox="0 0 420 85" role="img" aria-label="C1 contador, CV ${s.cycles}, PV 5, Q ${Number(s.complete)}"><path class="rail on" d="M15 12V70"/><path class="wire on" d="M15 38H70"/>${contact({tag:'Fin ciclo ↑',pass:s.countPulse},76,38)}<path class="wire ${s.countPulse?'on':''}" d="M82 38H165"/><g class="${s.complete?'on':''}"><rect x="165" y="10" width="180" height="60" rx="4"/><text x="255" y="26">CTU C1 · PV=5</text><text x="255" y="45">CV=${s.cycles} · Q=${Number(s.complete)}</text><text x="255" y="61">R = reiniciar C1</text></g><path class="wire ${s.complete?'on':''}" d="M345 38H405"/></svg>`;
 };}
